from taf.gnb.oam.coam.cu.interfaces.cuoam23r1 import CUOAM23R1
from taf.gnb.oam.coam.cu.schemas.internal.asm.copy_managed_objects_response_v1 import (
    CopyManagedObjectsResponseV1,
)
from taf.gnb.oam.coam.cu.schemas.internal.asm.network_slicing_diff_v1 import (
    NetworkSlicing,
)
from taf.gnb.oam.coam.cu.schemas.internal.asm.operation_state_resp_v1 import (
    OperationStateRespV1,
)
from taf.gnb.oam.coam.cu.schemas.internal.asm.revert_object_resp_v1 import (
    RevertObjectResponseV1,
)
from taf.gnb.oam.coam.cu.schemas.licensed.asm.rad_debug_param_update_response import (
    RadDebugParamUpdateResponse,
)
from taf.gnb.oam.coam.cu.schemas.licensed.asm.rad_domain_response import (
    RadDomainResponse,
)
from taf.gnb.oam.coam.cu.schemas.licensed.asm.rad_params_response import (
    RadParamsResponse,
)
from taf.gnb.oam.coam.cu.schemas.licensed.em_service.nms_response_v1 import (
    NmsResponseV1,
)
from taf.gnb.oam.coam.cu.services.licensed.emservice.emservice_licensed_v1 import (
    EMServiceLicensedV1,
)
from taf.gnb.oam.coam.cu.services.licensed.pm.pm_licensed_v1 import PMLICENSEDv1
from taf.gnb.oam.coam.cu.utilities.use_m2m_parser import enforce_use_m2m_type


class CUOAM23R2(CUOAM23R1):
    def __init__(self, con_details):
        super(CUOAM23R2, self).__init__(con_details)
        self.em_service_licensed_v1 = EMServiceLicensedV1(con_details=con_details)
        self.pm_licensed_v1 = PMLICENSEDv1(con_details=con_details)

    def get_nms(self, timeout=30, raw=False):
        response = self.em_service_licensed_v1.get_nms(timeout=timeout)
        return response if raw else NmsResponseV1.from_object_dict(response)

    def get_network_slicing(self, timeout=30):
        response = self.asm_v1.get_network_slicing(timeout=timeout).created
        return NetworkSlicing.from_object_dict(response)

    def lock_network_slicing(self, network_slicing_ids, timeout=30, raw=False):
        response = self.asm_v1.lock_network_slicing(network_slicing_ids=network_slicing_ids, timeout=timeout)
        return response if raw else OperationStateRespV1.from_object_dict(response)

    def get_operate_network_slicing_state(self, operation_id, timeout=30):
        response = self.asm_v1.get_operate_network_slicing_state(operation_id=operation_id, timeout=timeout)
        return OperationStateRespV1.from_object_dict(response)

    def unlock_network_slicing(self, network_slicing_ids, timeout=30, raw=False):
        response = self.asm_v1.unlock_network_slicing(network_slicing_ids=network_slicing_ids, timeout=timeout)
        return response if raw else OperationStateRespV1.from_object_dict(response)

    def copy_managed_objects_into_delta_plan(self, plan_id, source_plan_id, parent_mo_uuid, mo_uuid, new_instance_id,
                                             include_children_objects, timeout=30):
        response = self.asm_v1.copy_managed_objects_into_delta_plan(plan_id=plan_id,
                                                                    parent_mo_uuid=parent_mo_uuid,
                                                                    source_plan_id=source_plan_id,
                                                                    mo_uuid=mo_uuid,
                                                                    new_instance_id=new_instance_id,
                                                                    include_children_objects=include_children_objects,
                                                                    timeout=timeout)

        return CopyManagedObjectsResponseV1.from_object_dict(response)

    def get_copy_managed_objects_into_delta_plan_status(self, plan_id, action_id, timeout=30):
        response = self.asm_v1.get_copy_managed_objects_into_delta_plan_status(plan_id=plan_id,
                                                                               action_id=action_id,
                                                                               timeout=timeout)
        return CopyManagedObjectsResponseV1.from_object_dict(response)

    @enforce_use_m2m_type
    def cancel_snapshot_operation(self, operation_id, timeout=30, is_local=True, use_m2m=True):
        if use_m2m:
            self.asm_licensed.cancel_snapshot_operation(operation_id=operation_id, timeout=timeout)
        else:
            if is_local:
                self.asm_v1.cancel_local_snapshot_operation(operation_id=operation_id, timeout=timeout)
            else:
                self.asm_v1.cancel_remote_snapshot_operation(operation_id=operation_id, timeout=timeout)

    def get_all_raw_measurement_data(self, target_dir, target_file_name, timeout=30):
        return self.pm_licensed_v1.get_all_raw_measurement_data(target_dir=target_dir,
                                                                target_file_name=target_file_name,
                                                                timeout=timeout)

    def revert_managed_object(self, plan_id, mo_uuid, include_children=False, timeout=30):
        response = self.asm_v1.revert_managed_object(plan_id=plan_id,
                                                     mo_uuid=mo_uuid,
                                                     include_children=include_children,
                                                     timeout=timeout)
        return RevertObjectResponseV1.from_object_dict(response)

    def get_revert_managed_object_action(self, plan_id, action_id, timeout=30):
        response = self.asm_v1.get_revert_managed_object_action(plan_id=plan_id, action_id=action_id, timeout=timeout)
        return RevertObjectResponseV1.from_object_dict(response)

    @enforce_use_m2m_type
    def update_rad_debug_params(self, persistency=None, domain_name=None, parameters=None, node_id=None, timeout=30,
                                use_m2m=True, raw=False):
        if use_m2m:
            response = self.asm_licensed.update_rad_debug_params(persistency=persistency,
                                                                 node_id=node_id,
                                                                 domain_name=domain_name,
                                                                 parameters=parameters,
                                                                 timeout=timeout)
        else:
            response = self.asm_v1.update_rad_debug_params(persistency=persistency,
                                                           node_id=node_id,
                                                           domain_name=domain_name,
                                                           parameters=parameters,
                                                           timeout=timeout)

        return response if raw else RadDebugParamUpdateResponse.from_object_dict(response).to_dict()

    @enforce_use_m2m_type
    def get_rad_debug_params_update_operation(self, operation_id, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.asm_licensed.get_rad_debug_params_update_operation(operation_id=operation_id,
                                                                               timeout=timeout)
        else:
            response = self.asm_v1.get_rad_debug_params_update_operation(operation_id=operation_id, timeout=timeout)

        return response if raw else RadDebugParamUpdateResponse.from_object_dict(response).to_dict()

    @enforce_use_m2m_type
    def rad_reload_params(self, domain_name=None, param_name=None, non_default_only=False, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.asm_licensed.rad_reload_params(domain_name=domain_name,
                                                           param_name=param_name,
                                                           non_default_only=non_default_only,
                                                           timeout=timeout)
        else:
            response = self.asm_v1.rad_reload_params(domain_name=domain_name,
                                                     param_name=param_name,
                                                     non_default_only=non_default_only,
                                                     timeout=timeout)

        return response if raw else RadParamsResponse.from_object_dict(response).to_dict()

    @enforce_use_m2m_type
    def get_reload_params_operation(self, operation_id, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.asm_licensed.get_reload_params_operation(operation_id=operation_id, timeout=timeout)
        else:
            response = self.asm_v1.get_reload_params_operation(operation_id=operation_id, timeout=timeout)

        return response if raw else RadParamsResponse.from_object_dict(response).to_dict()

    @enforce_use_m2m_type
    def rad_reload_domains(self, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.asm_licensed.rad_reload_domains(timeout=timeout)
        else:
            response = self.asm_v1.rad_reload_domains(timeout=timeout)

        return response if raw else RadDomainResponse.from_object_dict(response).to_dict()

    @enforce_use_m2m_type
    def get_reload_domains_operation(self, operation_id, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.asm_licensed.get_reload_domains_operation(operation_id=operation_id, timeout=timeout)
        else:
            response = self.asm_v1.get_reload_domains_operation(operation_id=operation_id, timeout=timeout)

        return response if raw else RadDomainResponse.from_object_dict(response).to_dict()
